// Standalone Qwen3.8 Q2_0 expert microbenchmark. No model-serving process is touched.
// Sample files are generated by prepare_q38_tiered_expert_sample.py and stay off Git.
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <condition_variable>
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <fcntl.h>
#include <fstream>
#include <iostream>
#include <mutex>
#include <numeric>
#include <string>
#include <thread>
#include <unistd.h>
#include <vector>

#define CUDA_OK(expr) do { cudaError_t error=(expr); if(error!=cudaSuccess) { std::cerr << #expr << ": " << cudaGetErrorString(error) << "\n"; std::exit(2); } } while(0)
constexpr int H=2560, I=640, QK=64, QB=18, GATE_ROW=H/QK*QB, FULL_MATRIX=I*GATE_ROW;

__device__ float q2_dot(const uint8_t* weights, const float* x, int n) {
    float sum=0.0f;
    for(int b=0;b<n/QK;b++) {
        const uint8_t* block=weights+b*QB;
        const float scale=__half2float(*reinterpret_cast<const __half*>(block));
        for(int j=0;j<QK;j++) {
            const int q=(block[2+j/4] >> (2*(j%4))) & 3;
            sum += float(q-1)*scale*x[b*QK+j];
        }
    }
    return sum;
}

__global__ void gate_up(const uint8_t* gate,const uint8_t* up,const float* x,float* activation,int rows) {
    const int r=blockIdx.x*blockDim.x+threadIdx.x;
    if(r>=rows)return;
    const float g=q2_dot(gate+r*GATE_ROW,x,H);
    const float u=q2_dot(up+r*GATE_ROW,x,H);
    activation[r]=(g/(1.0f+expf(-g)))*u;
}

__global__ void down_project(const uint8_t* down,const float* activation,float* y,int rows) {
    const int h=blockIdx.x*blockDim.x+threadIdx.x;
    if(h>=H)return;
    y[h]=q2_dot(down+h*(rows/QK*QB),activation,rows);
}

std::vector<uint8_t> read_bytes(const std::string& path) {
    std::ifstream file(path,std::ios::binary|std::ios::ate);
    if(!file) { std::cerr << "cannot read " << path << "\n"; std::exit(2); }
    const size_t n=size_t(file.tellg());
    std::vector<uint8_t> bytes(n);
    file.seekg(0);
    file.read(reinterpret_cast<char*>(bytes.data()),n);
    if(!file) { std::cerr << "short read " << path << "\n"; std::exit(2); }
    return bytes;
}
std::vector<float> reference(const std::string& dir) {
    auto raw=read_bytes(dir+"/reference.f32");
    if(raw.size()!=H*sizeof(float)) { std::cerr<<"bad reference size\n";std::exit(2); }
    std::vector<float> output(H);
    std::memcpy(output.data(),raw.data(),raw.size());
    return output;
}
double max_error(const float* actual,const std::vector<float>& expected) {
    double error=0;
    for(int i=0;i<H;i++) error=std::max(error,double(std::abs(actual[i]-expected[i])));
    return error;
}
void verify(const float* actual,const std::vector<float>& expected,const char* label) {
    const double error=max_error(actual,expected);
    const double scale=*std::max_element(expected.begin(),expected.end(),[](float a,float b){return std::abs(a)<std::abs(b);});
    const double limit=2e-5+0.002*std::abs(scale);
    if(!std::isfinite(error)||error>limit) {
        std::cerr<<label<<" reference mismatch: max_abs_error="<<error<<" limit="<<limit<<"\n";
        std::exit(3);
    }
}
struct Stats {double mean,p50,p95;};
Stats stats(std::vector<double> sample) {
    const double mean=std::accumulate(sample.begin(),sample.end(),0.0)/sample.size();
    std::sort(sample.begin(),sample.end());
    return {mean,sample[sample.size()/2],sample[size_t(sample.size()*0.95)]};
}
void emit(const std::string& mode,int workers,int iterations,const Stats& s,double error,uint64_t disk_bytes) {
    std::cout<<"{\"mode\":\""<<mode<<"\",\"workers\":"<<workers
             <<",\"iterations\":"<<iterations<<",\"mean_us\":"<<s.mean
             <<",\"p50_us\":"<<s.p50<<",\"p95_us\":"<<s.p95
             <<",\"max_abs_error\":"<<error<<",\"direct_disk_bytes\":"<<disk_bytes
             <<",\"verified\":true}"<<std::endl;
}
struct Worker {
    int gpu=0,fd=-1,rows=0;
    size_t bytes=0,padded=0;
    uint8_t* host=nullptr;
    uint8_t* device=nullptr;
    float *input=nullptr,*act=nullptr,*out=nullptr,*host_out=nullptr;
    cudaStream_t stream=nullptr;
};
int main(int argc,char** argv) {
    if(argc!=5) { std::cerr<<"usage: tiered_expert_probe SAMPLE_DIR gpu0|gpu0_ram|gpu0_nvme|resident|ram|nvme WORKERS ITERS\n";return 64; }
    const std::string dir=argv[1],mode=argv[2];
    const int workers=std::atoi(argv[3]),iters=std::atoi(argv[4]);
    if(iters<1 || (mode!="gpu0" && mode!="gpu0_ram" && mode!="gpu0_nvme" && mode!="resident" && mode!="ram" && mode!="nvme") ||
       (workers!=1 && workers!=2 && workers!=5))return 64;
    auto expected=reference(dir);
    const auto full=read_bytes(dir+"/full.bin");
    if(full.size()!=3*FULL_MATRIX) { std::cerr<<"bad sample size\n";return 2; }
    int count=0; CUDA_OK(cudaGetDeviceCount(&count));
    if(count<workers+1) { std::cerr<<"not enough GPUs\n";return 2; }
    CUDA_OK(cudaSetDevice(0));
    cudaStream_t master; CUDA_OK(cudaStreamCreate(&master));
    float *d_hidden=nullptr,*d_result=nullptr,*h_hidden=nullptr,*h_result=nullptr,*d_full_act=nullptr;
    uint8_t* d_full=nullptr;
    CUDA_OK(cudaMalloc((void**)&d_hidden,H*sizeof(float)));
    CUDA_OK(cudaMalloc((void**)&d_result,H*sizeof(float)));
    CUDA_OK(cudaMalloc((void**)&d_full_act,I*sizeof(float)));
    CUDA_OK(cudaMalloc((void**)&d_full,full.size()));
    CUDA_OK(cudaHostAlloc((void**)&h_hidden,H*sizeof(float),cudaHostAllocPortable));
    CUDA_OK(cudaHostAlloc((void**)&h_result,H*sizeof(float),cudaHostAllocPortable));
    for(int h=0;h<H;h++)h_hidden[h]=float((h%31)-15)*0.02f;
    CUDA_OK(cudaMemcpy(d_hidden,h_hidden,H*sizeof(float),cudaMemcpyHostToDevice));
    CUDA_OK(cudaMemcpy(d_full,full.data(),full.size(),cudaMemcpyHostToDevice));
    auto gpu0_step=[&]{
        gate_up<<<(I+127)/128,128,0,master>>>(d_full,d_full+FULL_MATRIX,d_hidden,d_full_act,I);
        CUDA_OK(cudaGetLastError());
        down_project<<<(H+127)/128,128,0,master>>>(d_full+2*FULL_MATRIX,d_full_act,d_result,I);
        CUDA_OK(cudaGetLastError());
        CUDA_OK(cudaStreamSynchronize(master));
    };
    gpu0_step();
    CUDA_OK(cudaMemcpy(h_result,d_result,H*sizeof(float),cudaMemcpyDeviceToHost));
    verify(h_result,expected,"gpu0");
    if(mode=="gpu0" || mode=="gpu0_ram" || mode=="gpu0_nvme") {
        uint8_t* full_host=nullptr;
        int full_fd=-1;
        const size_t padded=(full.size()+4095)&~size_t(4095);
        if(mode!="gpu0") {
            void* aligned=nullptr;
            if(posix_memalign(&aligned,4096,padded)!=0) { std::cerr<<"aligned allocation failed\n";return 2; }
            full_host=static_cast<uint8_t*>(aligned);
            std::memcpy(full_host,full.data(),full.size());
            CUDA_OK(cudaHostRegister(full_host,padded,cudaHostRegisterPortable));
            if(mode=="gpu0_nvme") {
                const std::string path=dir+"/full_direct.bin";
                if(read_bytes(path).size()!=padded) { std::cerr<<"bad direct file size\n";return 2; }
                full_fd=open(path.c_str(),O_RDONLY|O_DIRECT);
                if(full_fd<0) { perror("O_DIRECT open");return 2; }
            }
        }
        std::vector<double> times;times.reserve(iters);
        for(int i=0;i<iters+20;i++) {
            auto begin=std::chrono::steady_clock::now();
            if(mode=="gpu0_nvme") {
                const ssize_t n=pread(full_fd,full_host,padded,0);
                if(n!=ssize_t(padded)) { perror("O_DIRECT pread");return 2; }
            }
            if(mode!="gpu0")CUDA_OK(cudaMemcpyAsync(d_full,full_host,full.size(),cudaMemcpyHostToDevice,master));
            gpu0_step();
            auto end=std::chrono::steady_clock::now();
            if(i>=20)times.push_back(std::chrono::duration<double,std::micro>(end-begin).count());
        }
        CUDA_OK(cudaMemcpy(h_result,d_result,H*sizeof(float),cudaMemcpyDeviceToHost));
        verify(h_result,expected,"gpu0");
        emit(mode,0,iters,stats(times),max_error(h_result,expected),
             mode=="gpu0_nvme"?uint64_t(padded)*uint64_t(iters+20):0);
        if(full_fd>=0)close(full_fd);
        if(full_host) { CUDA_OK(cudaHostUnregister(full_host));free(full_host); }
        return 0;
    }
    const int rows=I/workers;
    const size_t shard_bytes=size_t(rows)*(2*GATE_ROW+H/QK*QB);
    std::vector<Worker> ws(workers);
    for(int i=0;i<workers;i++) {
        Worker& w=ws[i];w.gpu=i+1;w.rows=rows;w.bytes=shard_bytes;
        w.padded=(shard_bytes+4095)&~size_t(4095);
        const std::string path=dir+"/shard_"+std::to_string(i)+".bin";
        auto shard=read_bytes(path);
        if(shard.size()!=w.padded) { std::cerr<<"bad shard file size\n";return 2; }
        void* aligned=nullptr;
        if(posix_memalign(&aligned,4096,w.padded)!=0) { std::cerr<<"aligned allocation failed\n";return 2; }
        w.host=static_cast<uint8_t*>(aligned);
        std::memcpy(w.host,shard.data(),w.padded);
        CUDA_OK(cudaSetDevice(w.gpu));
        CUDA_OK(cudaHostRegister(w.host,w.padded,cudaHostRegisterPortable));
        CUDA_OK(cudaHostAlloc((void**)&w.host_out,H*sizeof(float),cudaHostAllocPortable));
        CUDA_OK(cudaStreamCreate(&w.stream));
        CUDA_OK(cudaMalloc((void**)&w.device,w.bytes));
        CUDA_OK(cudaMalloc((void**)&w.input,H*sizeof(float)));
        CUDA_OK(cudaMalloc((void**)&w.act,rows*sizeof(float)));
        CUDA_OK(cudaMalloc((void**)&w.out,H*sizeof(float)));
        CUDA_OK(cudaMemcpy(w.device,w.host,w.bytes,cudaMemcpyHostToDevice));
        if(mode=="nvme") {
            w.fd=open(path.c_str(),O_RDONLY|O_DIRECT);
            if(w.fd<0) { perror("O_DIRECT open");return 2; }
        }
    }
    CUDA_OK(cudaSetDevice(0));
    std::mutex mu;std::condition_variable start,done;
    int epoch=0,completed=0;bool stopping=false;
    std::vector<std::thread> threads;
    for(int i=0;i<workers;i++)threads.emplace_back([&,i]{
        Worker& w=ws[i];
        CUDA_OK(cudaSetDevice(w.gpu));
        int seen=0;
        while(true) {
            {std::unique_lock<std::mutex> lock(mu);
             start.wait(lock,[&]{return stopping||epoch>seen;});
             if(stopping)return;seen=epoch;}
            if(mode=="nvme") {
                const ssize_t n=pread(w.fd,w.host,w.padded,0);
                if(n!=ssize_t(w.padded)) { perror("O_DIRECT pread");std::exit(2); }
            }
            if(mode!="resident")CUDA_OK(cudaMemcpyAsync(w.device,w.host,w.bytes,cudaMemcpyHostToDevice,w.stream));
            CUDA_OK(cudaMemcpyAsync(w.input,h_hidden,H*sizeof(float),cudaMemcpyHostToDevice,w.stream));
            const int gate_bytes=rows*GATE_ROW;
            gate_up<<<(rows+127)/128,128,0,w.stream>>>(w.device,w.device+gate_bytes,w.input,w.act,rows);
            CUDA_OK(cudaGetLastError());
            down_project<<<(H+127)/128,128,0,w.stream>>>(w.device+2*gate_bytes,w.act,w.out,rows);
            CUDA_OK(cudaGetLastError());
            CUDA_OK(cudaMemcpyAsync(w.host_out,w.out,H*sizeof(float),cudaMemcpyDeviceToHost,w.stream));
            CUDA_OK(cudaStreamSynchronize(w.stream));
            {std::lock_guard<std::mutex> lock(mu);completed++;}
            done.notify_one();
        }
    });
    std::vector<double> times;times.reserve(iters);
    for(int step=0;step<iters+20;step++) {
        const auto begin=std::chrono::steady_clock::now();
        CUDA_OK(cudaSetDevice(0));
        CUDA_OK(cudaMemcpyAsync(h_hidden,d_hidden,H*sizeof(float),cudaMemcpyDeviceToHost,master));
        CUDA_OK(cudaStreamSynchronize(master));
        {std::lock_guard<std::mutex> lock(mu);completed=0;epoch++;}
        start.notify_all();
        {std::unique_lock<std::mutex> lock(mu);done.wait(lock,[&]{return completed==workers;});}
        for(int h=0;h<H;h++) {
            float sum=0;
            for(int i=0;i<workers;i++)sum+=ws[i].host_out[h];
            h_result[h]=sum;
        }
        CUDA_OK(cudaMemcpyAsync(d_result,h_result,H*sizeof(float),cudaMemcpyHostToDevice,master));
        CUDA_OK(cudaStreamSynchronize(master));
        const auto end=std::chrono::steady_clock::now();
        if(step>=20)times.push_back(std::chrono::duration<double,std::micro>(end-begin).count());
    }
    {std::lock_guard<std::mutex> lock(mu);stopping=true;}
    start.notify_all();for(auto& t:threads)t.join();
    CUDA_OK(cudaMemcpy(h_result,d_result,H*sizeof(float),cudaMemcpyDeviceToHost));
    verify(h_result,expected,mode.c_str());
    emit(mode,workers,iters,stats(times),max_error(h_result,expected),
         mode=="nvme"?uint64_t(workers)*uint64_t(ws[0].padded)*uint64_t(iters+20):0);
    for(auto& w:ws) {
        CUDA_OK(cudaSetDevice(w.gpu));
        if(w.fd>=0)close(w.fd);
        CUDA_OK(cudaFree(w.device));CUDA_OK(cudaFree(w.input));CUDA_OK(cudaFree(w.act));CUDA_OK(cudaFree(w.out));
        CUDA_OK(cudaStreamDestroy(w.stream));CUDA_OK(cudaFreeHost(w.host_out));CUDA_OK(cudaHostUnregister(w.host));
        free(w.host);
    }
    CUDA_OK(cudaSetDevice(0));
    CUDA_OK(cudaFree(d_hidden));CUDA_OK(cudaFree(d_result));CUDA_OK(cudaFree(d_full_act));CUDA_OK(cudaFree(d_full));
    CUDA_OK(cudaFreeHost(h_hidden));CUDA_OK(cudaFreeHost(h_result));CUDA_OK(cudaStreamDestroy(master));
    return 0;
}